syntax:
Class with move constructor:

class ClassName {
public:
    // Move constructor
    ClassName(ClassName&& other) noexcept;
    // Move assignment operator
    ClassName& operator=(ClassName&& other) noexcept;
};

Function returning rvalue reference:

Type&& functionName();

code_example:
#include <iostream>
#include <vector>

class Buffer {
public:
    std::vector<int> data_;
    // Constructor
    Buffer() = default;
    // Move constructor
    Buffer(Buffer&& other) noexcept : data_(std::move(other.data_)) {
        std::cout << "Move constructor called" << std::endl;
    }
    // Move assignment
    Buffer& operator=(Buffer&& other) noexcept {
        if (this != &other) {
            data_ = std::move(other.data_);
            std::cout << "Move assignment called" << std::endl;
        }
        return *this;
    }
};

Buffer createBuffer() {
    Buffer buf;
    buf.data_.push_back(42);
    return buf; // Rvalue returned here
}

int main() {
    Buffer b1 = createBuffer(); // Move constructor invoked
    Buffer b2;
    b2 = createBuffer(); // Move assignment invoked
    return 0;
}
